import { Injectable } from '@angular/core';
import { BehaviorSubject } from 'rxjs';
import { CustomTextDefs } from '../../interfaces/customtext.interfaces';
import { customTextDefaults } from '../../objects/customTextDefaults';

@Injectable({
  providedIn: 'root'
})
export class CustomtextService {
  private customTexts: { [key: string]: BehaviorSubject<string | null> } = {};

  addCustomTexts(newTexts: { [key: string]: string }): void {
    Object.keys(newTexts).forEach(key => {
      this.addCustomText(key, newTexts[key]);
    });
  }

  addCustomTextsFromDefs(newTexts: CustomTextDefs): void {
    Object.keys(newTexts).forEach(key => {
      this.addCustomText(key, newTexts[key].defaultvalue);
    });
  }

  private addCustomText(key: string, value: string): void {
    if (typeof this.customTexts[key] === 'undefined') {
      this.customTexts[key] = new BehaviorSubject<string | null>(null);
    }
    this.customTexts[key].next(value);
  }

  getCustomText$(key: string): BehaviorSubject<string | null> {
    if (typeof this.customTexts[key] === 'undefined') {
      this.customTexts[key] = new BehaviorSubject<string | null>(null);
    }
    return this.customTexts[key];
  }

  restoreDefault(all: boolean): void {
    if (typeof this.customTexts === 'undefined') {
      return;
    }

    Object.keys(this.customTexts).forEach(k => {
      if (this.customTexts[k] && customTextDefaults[k]) {
        this.customTexts[k].next(customTextDefaults[k].defaultvalue);
      }
      if (all) {
        if (!(k in customTextDefaults) && this.customTexts[k]) {
          this.customTexts[k] = new BehaviorSubject<string | null>(null);
        }
      }
    });
  }

  getCustomText(key: string): string {
    if (typeof this.customTexts[key] === 'undefined') {
      return '';
    }
    return this.customTexts[key].getValue() ?? '';
  }

  getCustomTextKeys(): Array<string> {
    return Object.keys(this.customTexts);
  }
}

import { Pipe, PipeTransform } from '@angular/core';
import { Observable, of } from 'rxjs';
import { map, switchMap } from 'rxjs/operators';
import { CustomtextService } from '../../services/customtext/customtext.service';
import { environment } from '../../../../environments/environment';

/** Output depends on the environment.ts. If the given default value is an empty string: *) In Production, the function
 * returns an empty string; *) In Dev the function returns the key argument, for debugging purposes. */
@Pipe({
  name: 'customtext'
})
export class CustomtextPipe implements PipeTransform {
  constructor(private cts: CustomtextService) {}

  transform(defaultValue: string, key: string, ...replacements: Array<string | number>): Observable<string> {
    return of('...')
      .pipe(
        switchMap(() => this.cts.getCustomText$(key)),
        map(customText => {
          if (customText) {
            return customText;
          }
          // TODO change direct call of environment with Inject Token 'IS_PRODUCTION_MODE', somehow didn't work
          return environment.production ? defaultValue : (defaultValue || key);
        }),
        map(customText => {
          replacements
            .map(replacement => (typeof replacement === 'number' ? String(replacement) : replacement))
            .forEach(replacement => {
              // eslint-disable-next-line no-param-reassign
              customText = customText
                .replace('%s', replacement)
                .replace('%date', new Date(replacement).toLocaleString());
            });
          return customText;
        })
      );
  }
}

import { DomSanitizer, SafeUrl } from '@angular/platform-browser';
import { CustomtextService } from '../services/customtext/customtext.service';
import { KeyValuePairs } from '../../app.interfaces';
import {
  AppSettings,
  SysConfig,
  XmlSchemaVersions
} from '../interfaces/app-config.interfaces';
// eslint-disable-next-line import/no-relative-packages
import customTextsDefaultJSON from '../../../../../definitions/testtaker/custom-texts.json';

const customTextsDefault = customTextsDefaultJSON as {
  [k: string]: {
    'label': string,
    'defaultvalue': string
  }
};

export class AppConfig {
  sanitizer: DomSanitizer;
  cts: CustomtextService;
  defaultThemeName: string;
  customTexts: KeyValuePairs = {};
  version = '';
  veronaPlayerApiVersionMin: number = 0;
  veronaPlayerApiVersionMax: number = 0;
  iqbStandardResponseTypeMin: number = 0;
  iqbStandardResponseTypeMax: number = 0;
  xmlSchemaVersions: XmlSchemaVersions = {};
  appTitle = 'IQB-Testcenter';
  privacyNotice = '';
  trustedPrivacyNotice: SafeUrl | null = null;
  accessibilityNotice = '';
  trustedAccessibilityNotice: SafeUrl | null = null;
  legalNoticeHtml = '';
  trustedLegalNoticeHtml: SafeUrl | null = null;
  globalWarningText = '';
  globalWarningExpiredDay = '';
  globalWarningExpiredHour = '';
  bruteForceProtection: string[] = [];
  broadcastingServiceUri: string = '';
  fileServiceUri: string = '';
  themeName: string = '';
  passwordMinLength: number = 0;
  passwordPattern: string = '';

  constructor(sysConfig: SysConfig, cts: CustomtextService, defaultThemeName: string, sanitizer: DomSanitizer) {
    this.sanitizer = sanitizer;
    this.cts = cts;
    this.defaultThemeName = defaultThemeName;
    this.setCustomTexts(sysConfig.customTexts);
    this.setAppConfig(sysConfig.appConfig);
    this.customTexts = sysConfig.customTexts;
    this.version = sysConfig.version;
    this.veronaPlayerApiVersionMin = sysConfig.veronaPlayerApiVersionMin;
    this.veronaPlayerApiVersionMax = sysConfig.veronaPlayerApiVersionMax;
    this.iqbStandardResponseTypeMin = sysConfig.iqbStandardResponseTypeMin;
    this.iqbStandardResponseTypeMax = sysConfig.iqbStandardResponseTypeMax;
    this.xmlSchemaVersions = sysConfig.xmlSchemaVersions;
    this.bruteForceProtection = sysConfig.bruteForceProtection;
    this.broadcastingServiceUri = sysConfig.broadcastingServiceUri;
    this.fileServiceUri = sysConfig.fileServiceUri;
    this.passwordMinLength = sysConfig.passwordMinLength;
    this.passwordPattern = sysConfig.passwordPattern;
  }

  setCustomTexts(customTexts: KeyValuePairs): void {
    const ctSettings: { [k: string]: string } = {};
    Object.keys(customTextsDefault).forEach(k => {
      ctSettings[k] = customTextsDefault[k].defaultvalue;
    });
    if (customTexts) {
      Object.keys(customTexts).forEach(k => {
        ctSettings[k] = customTexts[k];
      });
    }
    this.cts.addCustomTexts(ctSettings);
  }

  setAppConfig(appConfig?: AppSettings): void {
    this.appTitle = 'IQB-Testcenter';
    this.privacyNotice = 'privacyNotice text nicht definiert';
    this.trustedPrivacyNotice = null;
    this.accessibilityNotice = 'accessibilityNotice text nicht definiert';
    this.trustedAccessibilityNotice = null;
    this.legalNoticeHtml = '<p>Anbieter:<br>Max Mustermann<br>Musterstraße 1<br>13088 Berlin<br>' +
      '<br>Kontakt:<br>Telefon: 030/1234567-8<br>Telefax: 030/1234567-9<br>E-Mail: mail@mustermann.de' +
      '<br>Website: www.mustermann.de</p>';
    this.trustedLegalNoticeHtml = null;
    this.globalWarningText = '';
    this.globalWarningExpiredDay = '';
    this.globalWarningExpiredHour = '';
    this.themeName = this.defaultThemeName;
    if (appConfig) {
      if (appConfig.appTitle) this.appTitle = appConfig.appTitle;
      if (appConfig.legalNoticeHtml) this.legalNoticeHtml = appConfig.legalNoticeHtml;
      if (appConfig.privacyNotice) this.privacyNotice = appConfig.privacyNotice;
      if (appConfig.accessibilityNotice) this.accessibilityNotice = appConfig.accessibilityNotice;
      if (appConfig.globalWarningText) this.globalWarningText = appConfig.globalWarningText;
      if (appConfig.globalWarningExpiredDay) this.globalWarningExpiredDay = appConfig.globalWarningExpiredDay;
      if (appConfig.globalWarningExpiredHour) {
        this.globalWarningExpiredHour = appConfig.globalWarningExpiredHour;
      }
      if (appConfig.themeName) this.themeName = appConfig.themeName;
    }
    this.trustedLegalNoticeHtml = this.sanitizer?.bypassSecurityTrustHtml(this.legalNoticeHtml) ?? '';
    this.trustedPrivacyNotice = this.sanitizer?.bypassSecurityTrustHtml(this.privacyNotice) ?? '';
    this.trustedAccessibilityNotice = this.sanitizer?.bypassSecurityTrustHtml(this.accessibilityNotice) ?? '';
  }

  getWarningMessage(): string {
    if (this.globalWarningExpiredDay) {
      return AppConfig.isWarningExpired(this.globalWarningExpiredDay, this.globalWarningExpiredHour) ?
        '' : this.globalWarningText;
    }
    return this.globalWarningText;
  }

  static isWarningExpired(warningDay: string, warningHour: string): boolean {
    const targetDate = new Date(warningDay);
    targetDate.setHours(Number(warningHour));
    return targetDate < new Date(Date.now());
  }

  getAppConfig(): AppSettings {
    return {
      appTitle: this.appTitle,
      legalNoticeHtml: this.legalNoticeHtml,
      privacyNotice: this.privacyNotice,
      accessibilityNotice: this.accessibilityNotice,
      globalWarningText: this.globalWarningText,
      globalWarningExpiredDay: this.globalWarningExpiredDay,
      globalWarningExpiredHour: this.globalWarningExpiredHour,
      themeName: this.themeName
    };
  }
}
